def quiz_for(slug):
    if slug in MANAGER_QUIZZES:
        return MANAGER_QUIZZES[slug]
    return PHOTO_QUIZZES.get(slug, [])


def public_quiz(slug):
    return [{'prompt': item['prompt'], 'options': list(item['options'])} for item in quiz_for(slug)]


def grade_quiz(slug, answers):
    questions = quiz_for(slug)
    if not questions or not isinstance(answers, list) or len(answers) != len(questions) or any(
        type(a) is not int or a not in range(len(item['options'])) for a, item in zip(answers, questions)
    ):
        raise ValueError('Ответьте на все вопросы теста.')
    correct = sum(a == item['correct'] for a, item in zip(answers, questions))
    return {'score': round(correct / len(questions) * 100), 'passed': correct == len(questions),
            'feedback': [{'correct': a == item['correct'], 'explanation': item['explanation']}
                         for a, item in zip(answers, questions)]}
